theorem MIPRE.AnswerReduction.cl_accepts_of_side {r : Role} {i : Fin 5} (hr : LDStep r i) {τ' : Ty}
    (hτ' : τ' ≠ .point) {x x' : X} {y y' : Coord P → F} {u v : Ans P F}
    (h : side S S' check ((r, (i.castSucc, .point)), x, y) ((r, (i.castSucc, τ')), x', y') u v
      = true) :
    CL.accepts hm (q1 S i .point y) (q1 S i τ' y') (ans1 u) (ans1 v) = true := by sorry

theorem MIPRE.AnswerReduction.cl_accepts_of_accepts {r : Role} {i : Fin 5} (hr : LDStep r i) (τ τ' : Ty) {x x' : X}
    {y y' : Coord P → F} {u v : Ans P F}
    (h : accepts S S' check ((r, (i.castSucc, τ)), x, y) ((r, (i.castSucc, τ')), x', y') u v
      = true) :
    CL.accepts hm (q1 S i τ y) (q1 S i τ' y') (ans1 u) (ans1 v) = true := by sorry

theorem MIPRE.AnswerReduction.cl_accepts_of_accepts6 {i : Fin 6} (hi : (i : ℕ) = 5) (τ τ' : Ty) {x x' : X}
    {y y' : Coord P → F} {u v : Ans P F}
    (h : accepts S S' check ((.oracle, (i, τ)), x, y) ((.oracle, (i, τ')), x', y') u v = true) :
    CL.accepts hm' (q6 S' τ y) (q6 S' τ' y') (ans6 u) (ans6 v) = true := by sorry
